      expect(empty.placeholder()).toBe(empty);
    });

    it('should handle multiple elements', () => {
      const forms = $('<form></form><form></form>');
      expect(forms.placeholder()).toBe(forms);
    });
  });

  describe('prioritize', () => {
    let $parent, $el1, $el2;

